// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g1, bytes32 g2) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 2 ether);

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g1);

        // General rule: a second lockInGuess from the same actor must revert.
        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(g2) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}
